            new Quote { Id = Source, Text = "Já myslím, že po mnoho staletí existuje takový ruský problém, že Rusko přesně neví, kde začíná a kde končí. I když je to největší země světa, má přesto pocit, že je taková trochu malá a že ji ohrožují i nepatrní sousedé, které kolem sebe má.", Author = "Václav Havel" },
            new Quote { Id = Source, Text = "Možná se ptáte, o jaké republice sním. Odpovídám: o republice samostatné, svobodné, demokratické, o republice hospodářsky prosperující a zároveň sociálně spravedlivé, zkrátka o republice lidské, která slouží člověku, a proto má naději, že i člověk poslouží jí. O republice všestranně vzdělaných lidí, protože bez nich nelze řešit žádný z našich problémů – lidských, ekonomických, ekologických, sociálních a politických.", Author = "Václav Havel" },
            new Quote { Id = Source, Text = "Na nikoho, kdo za naši dnešní svobodu tak či onak zaplatil, by nemělo být zapomenuto.", Author = "Václav Havel" },
            new Quote { Id = Source, Text = "Politika by neměla hrát roli estrády.", Author = "Václav Havel" },
