            new Quote { Id = Source, Text = "Přirozenou nevýhodou demokracie je, že těm, kdo to s ní myslí poctivě, nesmírně svazuje ruce, zatímco těm, kteří ji neberou vážně, umožňuje téměř vše.", Author = "Václav Havel" },
            new Quote { Id = Source, Text = "Žádám vás snažně, abyste nepodpořili ty, kteří vám slibují, že všechno vyřeší za vás. Takoví lidé chtějí, abyste jen mlčeli, poslouchali a drželi krok. Žádám vás snažně, abyste nepodpořili ty, kteří mají diktátorské sklony, příliš často mění názory, nejsou schopni se domluvit s jinými, nabízejí různá dobrodružná, nepromyšlená a neodpovědná řešení a kteří by se nejraději vrátili k centralistickému řízení všech našich společných věcí.", Author = "Václav Havel" },
